let lang='en';try{lang=localStorage.getItem('rs-language')==='vi'?'vi':'en';}catch{}
export const language=()=>lang;
export function setLanguage(value){lang=value==='vi'?'vi':'en';try{localStorage.setItem('rs-language',lang);}catch{}}
export function t(value){return lang==='vi'?(vi[value]??value):value;}
export function translateStatic(cloud){
 document.documentElement.lang=lang;
 const ids={sample:'Load sample',reset:'New workspace',import:'Import JSON',backup:'Backup','new-project':'New project',close:'Close',cancel:'Cancel'};
 for(const [id,key] of Object.entries(ids))document.getElementById(id).textContent=t(key);
 const keys={register:'Requirements',trace:'Traceability matrix',quality:'Quality review',history:'Version history',report:'Specification',scope:'Scope & stakeholders',governance:'Change control',testing:'Test execution',diagrams:'Diagrams'};
 document.querySelectorAll('[data-view]').forEach(el=>el.textContent=t(keys[el.dataset.view]));
 document.querySelector('label[for=project]').textContent=t('Workspace');
 document.querySelector('.brand small').textContent=t('Personal workspace');
 document.querySelector('.sidefoot').textContent=t(cloud?'Cloud workspace · Neon PostgreSQL':'Local workspace');
 document.querySelector('.skip').textContent=t('Skip to workspace');
 document.querySelector('#form button[type=submit]').textContent=t('Save artifact');
}
